    function run(address to, uint256 amt) public payable {
        // require a meaningful amount to avoid trivial no-op transfer
        require(to != address(0) || amt >= 0);

        // read before values
        address ownerAddr = c.owner();
        uint256 totalBefore = c.totalSupply();
        uint256 balSenderBefore = c.balanceOf(address(this));
        uint256 balToBefore = c.balanceOf(to);

        bool reverted;
        // attempt transfer from this contract (msg.sender for c will be this test contract)
        try c.transfer(to, amt) returns (bool) {
            reverted = false;
        } catch {
            reverted = true;
        }

        // read after values
        uint256 totalAfter = c.totalSupply();
        uint256 balSenderAfter = c.balanceOf(address(this));
        uint256 balToAfter = c.balanceOf(to);

        // If target is zero address then transfer must revert and nothing visible changes; otherwise we assert nothing here.
        assert(to != address(0) || (reverted && totalAfter == totalBefore && balSenderAfter == balSenderBefore && balToAfter == balToBefore));
    }
    receive() external payable { }
}

